package com.accessaudit.api;
import com.accessaudit.model.*; import com.accessaudit.service.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import com.accessaudit.repo.AdminAccountRepository; import org.springframework.security.access.AccessDeniedException;
@RestController @RequestMapping("/api")
public class AccessController {
 private final AccessService service; private final CatalogService catalogs; private final AdminAccountRepository accounts;
 public AccessController(AccessService service,CatalogService catalogs,AdminAccountRepository accounts){this.service=service;this.catalogs=catalogs;this.accounts=accounts;}
 @GetMapping("/requests") public List<AccessRequest> requests(Authentication auth){return isRequester(auth)?service.allForEmail(accountEmail(auth)):service.all();}
 @PostMapping("/requests") public ResponseEntity<?> create(@RequestBody Map<String,Object> body,Authentication auth){try{if(auth.getAuthorities().stream().anyMatch(a->a.getAuthority().equals("ROLE_REQUESTER"))){String ownEmail=accounts.findByUsernameIgnoreCase(auth.getName()).orElseThrow().getEmail();if(!ownEmail.equalsIgnoreCase(String.valueOf(body.getOrDefault("email",""))))return ResponseEntity.status(403).body(Map.of("error","Solicitantes só podem pedir acesso para a própria identidade."));}return ResponseEntity.status(HttpStatus.CREATED).body(service.create(withActor(body,auth.getName(),"actor")));}catch(IllegalArgumentException e){return bad(e);} }
 @PreAuthorize("hasAnyRole('ADMIN','APPROVER')") @PostMapping("/requests/{id}/decision") public ResponseEntity<?> decide(@PathVariable Long id,@RequestBody Map<String,Object> body,Authentication auth){try{return ResponseEntity.ok(service.decide(id,withActor(body,auth.getName(),"reviewer")));}catch(NoSuchElementException e){return ResponseEntity.status(404).body(Map.of("error",e.getMessage()));}catch(IllegalArgumentException|IllegalStateException e){return bad(e);}}
 @PreAuthorize("hasAnyRole('ADMIN','APPROVER')") @PostMapping("/requests/{id}/revoke") public ResponseEntity<?> revoke(@PathVariable Long id,@RequestBody Map<String,Object> body,Authentication auth){try{return ResponseEntity.ok(service.revoke(id,withActor(body,auth.getName(),"actor")));}catch(NoSuchElementException e){return ResponseEntity.status(404).body(Map.of("error",e.getMessage()));}catch(IllegalArgumentException|IllegalStateException e){return bad(e);}}
 @GetMapping("/requests/{id}/audit") public ResponseEntity<?> requestAudit(@PathVariable Long id,Authentication auth){if(isRequester(auth)&&!service.requestBelongsToEmail(id,accountEmail(auth)))return ResponseEntity.status(403).body(Map.of("error","Você só pode consultar a auditoria das suas próprias solicitações."));return ResponseEntity.ok(service.auditFor(id));}
 @GetMapping("/audit") public List<AuditEvent> audit(Authentication auth){return isRequester(auth)?service.auditForEmail(accountEmail(auth)):service.audit();}
 @GetMapping("/reviews") public List<AccessGrant> reviews(Authentication auth){return isRequester(auth)?service.reviewsForEmail(accountEmail(auth)):service.reviews();}
 @GetMapping("/accesses") public List<AccessGrant> accesses(Authentication auth){return isRequester(auth)?service.accessesForEmail(accountEmail(auth)):service.allAccesses();}
 @PreAuthorize("hasAnyRole('ADMIN','APPROVER')") @PostMapping("/accesses/{id}/review") public ResponseEntity<?> reviewAccess(@PathVariable Long id,@RequestBody Map<String,Object> body,Authentication auth){try{return ResponseEntity.ok(service.reviewAccess(id,withActor(body,auth.getName(),"actor")));}catch(NoSuchElementException e){return ResponseEntity.status(404).body(Map.of("error",e.getMessage()));}catch(IllegalArgumentException|IllegalStateException e){return bad(e);}}
 @GetMapping("/dashboard") public Map<String,Object> dashboard(Authentication auth){return isRequester(auth)?service.dashboardForEmail(accountEmail(auth)):service.dashboard();}
 @GetMapping("/users") public List<DirectoryUser> users(Authentication auth){return isRequester(auth)?catalogs.users().stream().filter(u->u.getEmail().equalsIgnoreCase(accountEmail(auth))).toList():catalogs.users();}
 @PostMapping("/users") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<?> createUser(@RequestBody Map<String,Object>b,Authentication auth){return catalogWrite(()->catalogs.saveUser(null,withActor(b,auth.getName(),"actor")));}
 @PutMapping("/users/{id}") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<?> updateUser(@PathVariable Long id,@RequestBody Map<String,Object>b,Authentication auth){return catalogWrite(()->catalogs.saveUser(id,withActor(b,auth.getName(),"actor")));}
 @DeleteMapping("/users/{id}") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<?> deactivateUser(@PathVariable Long id,@RequestBody(required=false) Map<String,Object>b,Authentication auth){return catalogWrite(()->{catalogs.deleteUser(id,withActor(b==null?Map.of():b,auth.getName(),"actor"));return Map.of("ok",true);});}
 @GetMapping("/systems") public List<ManagedSystem> systems(){return catalogs.systems();}
 @PostMapping("/systems") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<?> createSystem(@RequestBody Map<String,Object>b,Authentication auth){return catalogWrite(()->catalogs.saveSystem(null,withActor(b,auth.getName(),"actor")));}
 @PutMapping("/systems/{id}") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<?> updateSystem(@PathVariable Long id,@RequestBody Map<String,Object>b,Authentication auth){return catalogWrite(()->catalogs.saveSystem(id,withActor(b,auth.getName(),"actor")));}
 @DeleteMapping("/systems/{id}") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<?> deactivateSystem(@PathVariable Long id,@RequestBody(required=false) Map<String,Object>b,Authentication auth){return catalogWrite(()->{catalogs.deleteSystem(id,withActor(b==null?Map.of():b,auth.getName(),"actor"));return Map.of("ok",true);});}
 @GetMapping("/profiles") public List<AccessProfile> profiles(){return catalogs.profiles();}
 @PostMapping("/profiles") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<?> createProfile(@RequestBody Map<String,Object>b,Authentication auth){return catalogWrite(()->catalogs.saveProfile(null,withActor(b,auth.getName(),"actor")));}
 @PutMapping("/profiles/{id}") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<?> updateProfile(@PathVariable Long id,@RequestBody Map<String,Object>b,Authentication auth){return catalogWrite(()->catalogs.saveProfile(id,withActor(b,auth.getName(),"actor")));}
 @DeleteMapping("/profiles/{id}") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<?> deactivateProfile(@PathVariable Long id,@RequestBody(required=false) Map<String,Object>b,Authentication auth){return catalogWrite(()->{catalogs.deleteProfile(id,withActor(b==null?Map.of():b,auth.getName(),"actor"));return Map.of("ok",true);});}
 private boolean isRequester(Authentication auth){return auth.getAuthorities().stream().anyMatch(a->a.getAuthority().equals("ROLE_REQUESTER"));}
 private String accountEmail(Authentication auth){return accounts.findByUsernameIgnoreCase(auth.getName()).orElseThrow().getEmail();}
 private Map<String,Object> withActor(Map<String,Object> body,String actor,String key){Map<String,Object> copy=new HashMap<>(body==null?Map.of():body);copy.put(key,actor);return copy;}
 private ResponseEntity<?> catalogWrite(java.util.concurrent.Callable<?> action){try{return ResponseEntity.ok(action.call());}catch(NoSuchElementException e){return ResponseEntity.status(404).body(Map.of("error",e.getMessage()));}catch(IllegalArgumentException e){return bad(e);}catch(Exception e){return ResponseEntity.status(500).body(Map.of("error","Falha ao processar a operação."));}}
 private ResponseEntity<Map<String,String>> bad(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()==null?"Dados inválidos.":e.getMessage()));}
 @ExceptionHandler(AccessDeniedException.class) public ResponseEntity<?> forbidden(AccessDeniedException e){return ResponseEntity.status(403).body(Map.of("error","Seu perfil não tem permissão para esta operação."));}
 @ExceptionHandler(Exception.class) public ResponseEntity<?> error(Exception e){return ResponseEntity.status(500).body(Map.of("error","Erro interno ao processar solicitação."));}
}
